package cos.premy.mines.graphics;

import android.app.*;
import android.content.*;
import android.graphics.Bitmap;
import android.opengl.GLSurfaceView;
import android.os.*;
import android.view.*;
import android.widget.*;
import cos.premy.mines.*;
import cos.premy.mines.data.*;
import java.io.*;
import java.lang.reflect.Field;
import java.util.*;

/** Debug-only on-device acceptance runner. All game moves use real viewport touches and UI buttons. */
public final class DeviceChecks extends Instrumentation {
 private Bundle args;private GameActivity activity;private final StringBuilder log=new StringBuilder();private File output;
 @Override public void onCreate(Bundle a){super.onCreate(a);args=a;start();}
 @Override public void onStart(){Bundle result=new Bundle();output=new File(getTargetContext().getFilesDir(),"qa");output.mkdirs();
  try{String suite=args.getString("suite","flows");note("DEVICE "+Build.MANUFACTURER+" "+Build.MODEL+" Android "+Build.VERSION.RELEASE+" suite="+suite);
   if("perf".equals(suite))performance(Integer.parseInt(args.getString("seconds","720")));
   else if("showcase".equals(suite))showcase();
   else if("persistence".equals(suite))persistence(); else if("lifecycle".equals(suite))lifecycle();
   else if("languages".equals(suite))languages(); else if("options".equals(suite))options();
   else flows();
   note("PASS "+suite);write("results-"+suite+".txt",log.toString());result.putString("stream",log.toString());finish(Activity.RESULT_OK,result);
  }catch(Throwable failure){note("FAIL "+failure);StringWriter trace=new StringWriter();failure.printStackTrace(new PrintWriter(trace));note(trace.toString());write("failure.txt",log.toString());result.putString("stream",log.toString());finish(Activity.RESULT_CANCELED,result);}
 }
 private void note(String message){log.append(message).append('\n');Bundle b=new Bundle();b.putString("stream",message+"\n");sendStatus(0,b);android.util.Log.i("MinesQA",message);}
 private void write(String name,String value){try(FileOutputStream out=new FileOutputStream(new File(output,name))){out.write(value.getBytes("UTF-8"));}catch(IOException e){throw new IllegalStateException(e);}}
 private Object field(Object object,String name){try{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(Exception e){throw new IllegalStateException(e);}}
 private LoadedGame game(){return(LoadedGame)field(activity,"game");}
 private Game3dPanel panel(){return(Game3dPanel)field(activity,"game3d");}
 private BoardViewport viewport(){return(BoardViewport)activity.findViewById(R.id.board_viewport);}
 private BoardRenderer renderer(){return(BoardRenderer)field(viewport(),"renderer");}
 private void require(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 private void launch(BoardDefinition d){launch(GameActivity.newIntent(getTargetContext(),d));}
 private void launch(Intent intent){if(activity!=null)runOnMainSync(()->activity.finish());intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(GameActivity)startActivitySync(intent);waitForIdleSync();awaitFrame();}
 private void awaitFrame(){long limit=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<limit){if(activity.findViewById(R.id.board_viewport) instanceof BoardViewport){BoardRenderer r=renderer();if(r.drawn!=null&&r.drawn==r.next){SystemClock.sleep(50);return;}}SystemClock.sleep(40);}throw new AssertionError("No stable GLES frame");}
 private void click(int id){runOnMainSync(()->{View b=activity.findViewById(id);require(b!=null&&b.isEnabled(),"Disabled button "+id);b.performClick();});waitForIdleSync();}
 private void deck(int z){int max=10;while(game().status.getLevel()!=z&&max-->0){click(R.id.board_next);awaitFrame();}require(game().status.getLevel()==z,"Layer navigation");}
 private void touch(float x,float y){long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0);sendPointerSync(down);down.recycle();SystemClock.sleep(24);MotionEvent up=MotionEvent.obtain(now,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,y,0);sendPointerSync(up);up.recycle();waitForIdleSync();}
 private void select(MineCoord c){deck(c.z);awaitFrame();BoardRenderer.Frame f=renderer().drawn;float[] m=f.camera.viewProjection;float x=f.scene.x(c.x),y=BoardScene.layerY(c.z)+BoardScene.top(f.scene.cell(c.x,c.y)),z=f.scene.z(c.y);float w=m[3]*x+m[7]*y+m[11]*z+m[15],px=(m[0]*x+m[4]*y+m[8]*z+m[12])/w,py=(m[1]*x+m[5]*y+m[9]*z+m[13])/w;int[] location=new int[2];runOnMainSync(()->viewport().getLocationOnScreen(location));float sx=location[0]+(px+1)*f.camera.width/2,sy=location[1]+(1-py)*f.camera.height/2;require(sx>=location[0]&&sx<location[0]+f.camera.width&&sy>=location[1]&&sy<location[1]+f.camera.height,"Projected cell offscreen");touch(sx,sy);awaitFrame();MineCoord selected=(MineCoord)field(panel(),"selected");require(selected!=null&&selected.x==c.x&&selected.y==c.y&&selected.z==c.z,"Pick mismatch at "+c.x+","+c.y+","+c.z);}
 private void open(int id){MineCoord c=game().definition.coord(id);select(c);click(R.id.board_open);awaitFrame();require(game().board.getMine(c.z,c.y,c.x).getStatus()==MineStatus.OPENED,"Open did not apply");}
 private void flag(int id){select(game().definition.coord(id));click(R.id.board_flag);awaitFrame();}
 private void shot(String name){Bitmap bitmap=getUiAutomation().takeScreenshot();require(bitmap!=null,"Screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(output,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new IllegalStateException(e);}finally{bitmap.recycle();}}
 private void focus(){click(R.id.board_focus);awaitFrame();}
 private void finishFlags(){LoadedGame g=game();for(int i=0;i<g.definition.present.length&&g.status.stillPlaying();i++){MineCoord c=g.definition.coord(i);Mine cell=g.board.getMine(c.z,c.y,c.x);if(cell.getIsReal()&&cell.getStatus()!=MineStatus.BLOCKED)flag(i);}require(g.status.hasUserWon(),"Flag victory did not occur");}
 private void flows(){
  launch(new BoardDefinition("classic",5,2,7,0,12345,""));focus();LoadedGame g=game();open(g.definition.start);require(!g.board.getMine(1,0,0).getIsReal(),"First reveal unsafe");int wrong=-1;for(int i=0;i<50;i++){MineCoord c=g.definition.coord(i);Mine cell=g.board.getMine(c.z,c.y,c.x);if(!cell.getIsReal()&&cell.getStatus()==MineStatus.UNBLOCKED){wrong=i;break;}}flag(wrong);for(int i=0;i<50;i++){MineCoord c=g.definition.coord(i);if(g.board.getMine(c.z,c.y,c.x).getIsReal())flag(i);}require(g.status.stillPlaying(),"Incorrect flag accepted as victory");flag(wrong);require(g.status.hasUserWon(),"Classic victory");shot("classic-win");note("PASS classic: first-safe, wrong flag blocks victory, flag/unflag, win");
  for(int level=0;level<3;level++){launch(GameSetup.create("escape",5,2,7,level));focus();g=game();shot("escape-"+level+"-ready");BoardDefinition d=g.definition;int[] previous=new int[d.present.length];Arrays.fill(previous,-1);ArrayDeque<Integer> queue=new ArrayDeque<>();queue.add(d.start);previous[d.start]=d.start;while(!queue.isEmpty()){int id=queue.remove();for(int n:d.neighbors(id)){MineCoord c=d.coord(n);if(previous[n]<0&&!g.board.getMine(c.z,c.y,c.x).getIsReal()){previous[n]=id;queue.add(n);}}}require(previous[d.exit]>=0,"Escape no route");List<Integer> route=new ArrayList<>();for(int i=d.exit;i!=d.start;i=previous[i])route.add(i);Collections.reverse(route);for(int id:route)open(id);require(g.status.hasUserWon(),"Escape route not won");shot("escape-"+level+"-win");note("PASS escape "+level+": top entrance to deepest exit via "+route.size()+" opened cells");}
  if("levels".equals(args.getString("suite")))return;
  for(int level=0;level<3;level++){launch(GameSetup.create("puzzle",5,2,7,level));focus();g=game();click(R.id.board_hint);require(g.hintsUsed==1&&g.pendingHint!=null,"Hint not recorded");require(!g.hintSources.isEmpty()||g.pendingHint.sources.isEmpty(),"Hint source missing");int count=0;while(g.status.stillPlaying()&&count++<160){LogicSolver.Hint h=g.findHint();require(h!=null,"Puzzle stalled before win");if(h.mine)flag(h.cell);else{MineCoord c=g.definition.coord(h.cell);if(g.board.getMine(c.z,c.y,c.x).getStatus()==MineStatus.BLOCKED)flag(h.cell);open(h.cell);}}require(g.status.hasUserWon(),"Logic puzzle failed");note("PASS puzzle "+level+": solved "+count+" public deductions through UI");}
  for(int level=0;level<3;level++){launch(GameSetup.create("fault",5,2,7,level));focus();g=game();open(g.definition.start);for(int z=0;z<g.definition.layers;z++){deck(z);for(int[] xy:new int[][]{{0,0},{4,4},{0,4},{4,0},{2,2}})if(g.board.present(z,xy[1],xy[0]))select(new MineCoord(xy[0],xy[1],z));}shot("fault-"+level);finishFlags();note("PASS fault "+level+": real holes, corner selections, classic victory");}
  launch(new BoardDefinition("scan",5,2,7,0,12345,""));focus();g=game();open(g.definition.start);int found=0;for(int i=0;i<50&&found<3;i++){MineCoord c=g.definition.coord(i);Mine cell=g.board.getMine(c.z,c.y,c.x);if(!cell.getIsReal()&&cell.getNeighbors()>0){if(cell.getStatus()!=MineStatus.OPENED)open(i);select(c);int priorScans=g.scansLeft;click(R.id.board_scan);if(found<2){require(g.scansLeft==priorScans-1,"Scan button did not consume one use");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();}final int[] split=new int[2];final LoadedGame target=g;runOnMainSync(()->{int[] result=target.scan(c);split[0]=result==null?-1:result[0];split[1]=result==null?-1:result[1];});if(found<2)require(split[0]+split[1]==cell.getNeighbors(),"Scan sum");else require(split[0]==-1,"Third scan accepted");found++;}}require(g.scansLeft==0,"Scan budget");note("PASS scan: same + adjacent totals, two uses, third denied");finishFlags();
  launch(GameSetup.create("daily",5,3,10,0));focus();g=game();byte[] initial=g.board.saveCells();BoardDefinition day=g.definition;finishFlags();launch(day);require(Arrays.equals(initial,game().board.saveCells()),"Daily retry changed layout/start");note("PASS daily: same seed/start on retry, win and records");
  launch(new BoardDefinition("classic",15,8,540,0,935,""));focus();g=game();open(g.definition.start);for(int z:new int[]{7,4,0}){deck(z);for(int[] xy:new int[][]{{0,0},{14,0},{0,14},{14,14},{7,7}})select(new MineCoord(xy[0],xy[1],z));}byte[] before=g.board.saveCells();gesture(260,1100,800,1450,15);require(Arrays.equals(before,g.board.saveCells()),"Orbit modified cells");pinch();require(Arrays.equals(before,g.board.saveCells()),"Pinch changed board");click(R.id.board_reset);awaitFrame();for(int i=0;i<16;i++)click(R.id.board_next);awaitFrame();require(Arrays.equals(before,g.board.saveCells()),"Rapid layer switch modified cells");shot("maximum-board");note("PASS maximum 15x15x8: corners and inner layer, orbit and rapid switches preserve board");
 }
 private void gesture(float x0,float y0,float x1,float y1,int steps){long began=SystemClock.uptimeMillis();for(int i=0;i<=steps;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==steps?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;float a=i/(float)steps;MotionEvent e=MotionEvent.obtain(began,SystemClock.uptimeMillis(),action,x0+(x1-x0)*a,y0+(y1-y0)*a,0);sendPointerSync(e);e.recycle();SystemClock.sleep(16);}waitForIdleSync();awaitFrame();}
 private void showcase(){launch(GameActivity.newIntent(getTargetContext(),5,2,8).putExtra("showcase",true));focus();shot("showcase-ready");open(game().definition.index(2,3,0));select(new MineCoord(1,4,0));click(R.id.board_flag);awaitFrame();shot("showcase-flag");select(new MineCoord(4,3,0));click(R.id.board_open);require(game().status.outcome()==2,"Mine did not end game");shot("blast-early");SystemClock.sleep(700);shot("blast-dust");SystemClock.sleep(2000);shot("blast-settling");SystemClock.sleep(4000);require(field(activity,"result")!=null,"Missing delayed result");shot("blast-result");note("PASS approved-layout slice: safe clue, flag, selected mine, explosion, delayed result");}
 private void pinch(){int[] location=new int[2];runOnMainSync(()->viewport().getLocationOnScreen(location));float cy=location[1]+viewport().getHeight()*.5f,cx=viewport().getWidth()*.5f;long down=SystemClock.uptimeMillis();
  for(int step=0;step<23;step++){int count=step==0||step==22?1:2;int action=step==0?MotionEvent.ACTION_DOWN:step==1?MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT):step==21?MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT):step==22?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;float radius=120+Math.min(step,20)*7,shift=Math.max(0,step-10)*5;MotionEvent.PointerProperties[] properties=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[count];for(int i=0;i<count;i++){properties[i]=new MotionEvent.PointerProperties();properties[i].id=i;properties[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=cx+(i==0?-radius:radius)+shift;coords[i].y=cy;coords[i].pressure=1;coords[i].size=1;}MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,count,properties,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);sendPointerSync(e);e.recycle();SystemClock.sleep(20);}waitForIdleSync();awaitFrame();}
 private void lifecycle(){launch(GameActivity.newIntent(getTargetContext(),5,2,8).putExtra("showcase",true));focus();select(new MineCoord(4,3,0));click(R.id.board_open);SystemClock.sleep(450);getTargetContext().startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));SystemClock.sleep(350);LoadedGame previous=game();long phase=previous.status.explosion.elapsed();SystemClock.sleep(1500);require(previous.status.explosion.elapsed()==phase,"Explosion advanced in background");launch(new Intent(getTargetContext(),GameActivity.class).putExtra("resumeSession",true));require(game().status.outcome()==2&&game().status.explosion.cell!=null,"Failure/effect state missing");require(game().status.explosion.elapsed()>=phase&&game().status.explosion.elapsed()<phase+2500,"Explosion restarted instead of resuming");SystemClock.sleep(10500);require(!game().status.explosion.animating(),"Explosion never settled");Bundle saved=new Bundle();runOnMainSync(()->game().save(saved));LoadedGame restored=new LoadedGame(getTargetContext(),game().definition,saved);restored.status.resume();require(!restored.status.explosion.animating(),"Finished blast replayed after restore");note("PASS explosion: pause freezes phase, cold activity restore resumes phase, completed effect never replays");
  launch(GameSetup.create("puzzle",5,2,7,1));focus();LoadedGame g=game();click(R.id.board_hint);byte[] cells=g.board.saveCells();int hints=g.hintsUsed;ActivityMonitor monitor=addMonitor(GameActivity.class.getName(),null,false);runOnMainSync(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));Activity replacement=waitForMonitorWithTimeout(monitor,12000);removeMonitor(monitor);require(replacement instanceof GameActivity,"Landscape recreation not observed");activity=(GameActivity)replacement;awaitFrame();require(Arrays.equals(cells,game().board.saveCells())&&game().hintsUsed==hints,"Rotation lost board/hints");SystemClock.sleep(800);shot("landscape-restored");monitor=addMonitor(GameActivity.class.getName(),null,false);runOnMainSync(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));replacement=waitForMonitorWithTimeout(monitor,12000);removeMonitor(monitor);require(replacement instanceof GameActivity,"Portrait recreation not observed");activity=(GameActivity)replacement;awaitFrame();require(Arrays.equals(cells,game().board.saveCells()),"Portrait lost board");note("PASS Android task recreation: portrait/landscape preserve cells, hints and playable renderer");
 }
 private void persistence(){launch(new BoardDefinition("scan",5,3,11,0,294,""));focus();LoadedGame g=game();open(g.definition.start);int id=0;while(!g.definition.present[id]||g.board.getMine(g.definition.coord(id).z,g.definition.coord(id).y,g.definition.coord(id).x).getStatus()==MineStatus.OPENED)id++;flag(id);deck(1);Bundle saved=new Bundle();runOnMainSync(()->{g.save(saved);panel().save(saved);SessionStore.save(getTargetContext(),saved);});byte[] before=g.board.saveCells();long elapsed=g.status.elapsedMillis();getTargetContext().startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));SystemClock.sleep(2500);require(g.status.elapsedMillis()-elapsed<500,"Background time advanced");Intent restore=new Intent(getTargetContext(),GameActivity.class).putExtra("resumeSession",true);launch(restore);require(Arrays.equals(before,game().board.saveCells()),"Restored cells changed");require(game().status.getLevel()==1,"Layer not restored");require(Math.abs(game().status.elapsedMillis()-elapsed)<1500,"Elapsed not restored");shot("restored-session");note("PASS background: timer pauses; disk checkpoint restores board, flags, layer and elapsed");}
 private void languages(){for(String language:new String[]{"zh","en"}){android.content.res.Configuration c=new android.content.res.Configuration(getTargetContext().getResources().getConfiguration());c.setLocale(new Locale(language));Context local=getTargetContext().createConfigurationContext(c);require(MineTheme.mode(local,"escape").equals(language.equals("zh")?"矿井撤离":"Mine escape"),"Mode locale");for(String mode:new String[]{"classic","escape","puzzle","fault","scan","daily"})require(!MineTheme.mode(local,mode).isEmpty(),"Missing mode name");}note("PASS Chinese and English mode names/resources");}
 private void options(){
  SharedPreferences prefs=getTargetContext().getSharedPreferences("cos.premy.mines.settings",0);boolean wasSound=prefs.getBoolean("sound",true),wasReduced=prefs.getBoolean("reducedEffects",false);
  Activity settings=startActivitySync(new Intent(getTargetContext(),OptionActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  runOnMainSync(()->{Switch sound=settings.findViewById(R.id.option_sound),reduced=settings.findViewById(R.id.option_reduced);if(sound.isChecked())sound.performClick();if(!reduced.isChecked())reduced.performClick();settings.finish();});
  launch(new BoardDefinition("scan",5,2,7,0,12345,""));require(!(boolean)field(field(panel(),"sound"),"enabled"),"Sound switch ignored");require(renderer().next.reduced,"Reduced effects switch ignored");shot("reduced-effects");
  Activity restoreSettings=startActivitySync(new Intent(getTargetContext(),OptionActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  runOnMainSync(()->{Switch sound=restoreSettings.findViewById(R.id.option_sound),reduced=restoreSettings.findViewById(R.id.option_reduced);if(sound.isChecked()!=wasSound)sound.performClick();if(reduced.isChecked()!=wasReduced)reduced.performClick();restoreSettings.finish();});
  note("PASS options: real switches disable audio and reduce renderer effects; original preferences restored");
  launch(new BoardDefinition("scan",5,2,7,0,12345,""));focus();runOnMainSync(()->{Bundle state=new Bundle();game().save(state);panel().save(state);Game3dPanel old=panel();old.setActive(false);old.stopSurface();android.content.res.Configuration config=new android.content.res.Configuration(activity.getResources().getConfiguration());config.setLocale(Locale.ENGLISH);Context english=new android.view.ContextThemeWrapper(activity.createConfigurationContext(config),R.style.AppTheme);FrameLayout root=(FrameLayout)field(activity,"boardRoot");root.removeView(old);Game3dPanel replacement=new Game3dPanel(english,game(),state,()->{},()->{});try{Field f=GameActivity.class.getDeclaredField("game3d");f.setAccessible(true);f.set(activity,replacement);}catch(Exception e){throw new IllegalStateException(e);}root.addView(replacement,new FrameLayout.LayoutParams(-1,-1));replacement.startSurface();replacement.setActive(true);});awaitFrame();require(((TextView)activity.findViewById(R.id.board_open)).getText().toString().equals("Open"),"English controls");shot("english-board");note("PASS English controls in injected English Android context; device language unchanged");
  runOnMainSync(()->{try{java.lang.reflect.Method method=GameActivity.class.getDeclaredMethod("fallbackAfterRenderFailure");method.setAccessible(true);method.invoke(activity);}catch(Exception e){throw new IllegalStateException(e);}});waitForIdleSync();require(activity.findViewById(R.id.board_viewport) instanceof FlatBoardViewport,"Fallback missing");SystemClock.sleep(250);FlatBoardViewport flat=activity.findViewById(R.id.board_viewport);int[] location=new int[2];runOnMainSync(()->flat.getLocationOnScreen(location));float left=(float)field(flat,"left"),top=(float)field(flat,"top"),step=(float)field(flat,"step");touch(location[0]+left+step*.5f,location[1]+top+step*.5f);click(R.id.board_open);require(game().board.getFactorized(),"Fallback open failed");LoadedGame g=game();int scanCell=-1;for(int i=25;i<50;i++){MineCoord c=g.definition.coord(i);Mine m=g.board.getMine(c.z,c.y,c.x);if(!m.getIsReal()&&m.getNeighbors()>0){scanCell=i;break;}}require(scanCell>=0,"No scan candidate");MineCoord c=g.definition.coord(scanCell);touch(location[0]+left+step*(c.x+.5f),location[1]+top+step*(c.y+.5f));if(g.board.getMine(c.z,c.y,c.x).getStatus()!=MineStatus.OPENED)click(R.id.board_open);click(R.id.board_scan);require(g.scansLeft==1,"Fallback scan failed");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);shot("flat-fallback");note("PASS injected renderer failure: same board and native controls remain playable; scan consumes one use");
 }
 private void performance(int seconds){launch(new BoardDefinition("classic",15,8,540,0,935,""));open(game().definition.start);click(R.id.board_overview);awaitFrame();BoardRenderer r=renderer();long startFrames=(long)field(r,"frames"),start=SystemClock.elapsedRealtime();runOnMainSync(()->viewport().setRenderMode(GLSurfaceView.RENDERMODE_CONTINUOUSLY));PowerManager power=(PowerManager)getTargetContext().getSystemService(Context.POWER_SERVICE);int checkpoint=0;
  while(SystemClock.elapsedRealtime()-start<seconds*1000L){int[] pos=new int[2];runOnMainSync(()->viewport().getLocationOnScreen(pos));gesture(400,pos[1]+viewport().getHeight()*.45f,650,pos[1]+viewport().getHeight()*.52f,10);SystemClock.sleep(500);long elapsed=SystemClock.elapsedRealtime()-start;if(elapsed/60000>=checkpoint){checkpoint++;long frames=(long)field(r,"frames")-startFrames;note("PERF elapsedMs="+elapsed+" rendered="+frames+" cadenceFps="+String.format(Locale.ROOT,"%.2f",frames*1000.0/elapsed)+" pssKb="+android.os.Debug.getPss()+" thermal="+(Build.VERSION.SDK_INT>=29?power.getCurrentThermalStatus():-1));}}
  long elapsed=SystemClock.elapsedRealtime()-start,frames=(long)field(r,"frames")-startFrames;runOnMainSync(()->viewport().setRenderMode(GLSurfaceView.RENDERMODE_WHEN_DIRTY));note("PERF FINAL elapsedMs="+elapsed+" rendered="+frames+" cadenceFps="+String.format(Locale.ROOT,"%.2f",frames*1000.0/elapsed)+" pssKb="+android.os.Debug.getPss()+" thermal="+(Build.VERSION.SDK_INT>=29?power.getCurrentThermalStatus():-1));shot("perf-final");}
}



